#!/usr/bin/env bash
# Creates .env with random credentials if it does not exist yet. Existing files are kept.
source "$(dirname "$0")/lib.sh"

if [ -f "$ENV_FILE" ]; then
  log ".env already exists, keeping it"
  exit 0
fi

secret() { openssl rand -hex "$1"; }

umask 077
cat > "$ENV_FILE" <<EOF
# Generated by deploy/scripts/init-env.sh for the local test cluster. Never commit this file.
RMQV_ADMIN_USER=rmqv_admin
RMQV_ADMIN_PASSWORD=$(secret 24)
RMQV_APP_USER=rmqv_app
RMQV_APP_PASSWORD=$(secret 24)
RMQV_ERLANG_COOKIE=$(secret 32 | tr '[:lower:]' '[:upper:]')
RMQV_VHOST=rmqv
EOF
log "generated $ENV_FILE with random credentials (mode 600)"
